BEGIN;
CREATE TABLE IF NOT EXISTS claim_connector_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,source_id TEXT NOT NULL,source_version TEXT NOT NULL,payload_hash CHAR(64) NOT NULL,status TEXT NOT NULL,provider_receipt JSONB,freshness_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,source_id,source_version));
CREATE TABLE IF NOT EXISTS governed_claims(tenant_id TEXT NOT NULL,id TEXT NOT NULL,claimant_id TEXT NOT NULL,policy_ref TEXT NOT NULL,policy_version TEXT NOT NULL,jurisdiction TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'intake',version INTEGER NOT NULL DEFAULT 1,input JSONB NOT NULL,evaluation JSONB NOT NULL,request_hash CHAR(64) NOT NULL,idempotency_key TEXT NOT NULL,created_by TEXT NOT NULL,reviewed_by TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS claim_events(seq BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,claim_id TEXT NOT NULL,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,reason TEXT,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),FOREIGN KEY(tenant_id,claim_id) REFERENCES governed_claims(tenant_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS claim_outbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,claim_id TEXT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,payload JSONB NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,lease_token UUID,lease_expires_at TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),provider_receipt JSONB,last_error_code TEXT,FOREIGN KEY(tenant_id,claim_id) REFERENCES governed_claims(tenant_id,id),UNIQUE(tenant_id,provider,idempotency_key));
CREATE INDEX IF NOT EXISTS claim_state_idx ON governed_claims(tenant_id,state,updated_at);CREATE INDEX IF NOT EXISTS claim_outbox_ready_idx ON claim_outbox(status,next_attempt_at);
CREATE OR REPLACE FUNCTION claim_events_append_only() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'claim events are append-only';END$$;DROP TRIGGER IF EXISTS claim_events_append_only_trigger ON claim_events;CREATE TRIGGER claim_events_append_only_trigger BEFORE UPDATE OR DELETE ON claim_events FOR EACH ROW EXECUTE FUNCTION claim_events_append_only();
COMMIT;
